// 雙指標：跳過非英數字元，忽略大小寫比較
// 時間複雜度: O(n)，空間複雜度: O(1)
function isPalindrome(s) {
    const isAlnum = (c) => /[a-z0-9]/i.test(c);
    let left = 0, right = s.length - 1;
    while (left < right) {
        while (left < right && !isAlnum(s[left]))
            left++;
        while (left < right && !isAlnum(s[right]))
            right--;
        if (s[left].toLowerCase() !== s[right].toLowerCase())
            return false;
        left++;
        right--;
    }
    return true;
}

