#include <string>
#include <cctype>

class Solution {
public:
    /**
     * 使用雙指標檢查回文
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    bool isPalindrome(std::string s) {
        int left = 0, right = s.length() - 1;

        while (left < right) {
            // 跳過非字母數字字符（左指標）
            while (left < right && !isalnum(s[left])) {
                left++;
            }

            // 跳過非字母數字字符（右指標）
            while (left < right && !isalnum(s[right])) {
                right--;
            }

            // 比較字符（轉換為小寫）
            if (tolower(s[left]) != tolower(s[right])) {
                return false;
            }

            // 移動指標
            left++;
            right--;
        }

        return true;
    }
};

